{"command": "cd /tmp/t && python3 - <<'EOF'
import struct
class T:
    def __init__(self,b): self.b=b; self.i=0
    def varint(self):
        r=0;s=0
        while True:
            c=self.b[self.i]; self.i+=1
            r |= (c&0x7f)<<s; s+=7
            if not c&0x80: return r
    def zigzag(self):
        n=self.varint()
        return (n>>1) ^ -(n&1)
    def skip(self):
        # compact: byte = (delta<<4)|type
        h=self.b[self.i]; self.i+=1
        typ=h&0x0f; delta=h>>4
        if typ==0: return None
        return typ
def rd(t, tid):
    # read field of type tid at current pos (after header)
    if tid==1: return True
    elif tid==2: return False
    elif tid==3: return t.zigzag()   # i8
    elif tid==4: return t.zigzag()   # i16
    elif tid==5: return t.zigzag()   # i32
    elif tid==6: return t.zigzag()   # i64
    elif tid==7: 
        n=t.varint(); v=t.b[t.i:t.i+n]; t.i+=n; return v
    elif tid==8:
        n=t.varint(); return list(t.b[t.i:t.i+n]); t.i+=n
    elif tid==9:
        sz,et=t.varint(), None
        h=t.b[t.i]; t.i+=1; et=h&0xf
        res=[]
        while sz>0:
            block = min(sz, 16) if et in (3,4,5,6) else min(sz,1)
            pass
        return ("LIST-UNIMPL",)
    elif tid==12:
        res={}
        while True:
            h=t.b[t.i]
            if h==0: t.i+=1; break
            t.i+=1; delta=h>>4; tid2=h&0xf
            res[delta]=rd(t,tid2)
        return res
    else:
        raise Exception("t "+str(tid))
data=open('/workspace/assets/userdata.parquet','rb').read()
mlen=struct.unpack('<I', data[-8:-4])[0]
foot=data[-8-mlen:-8]
t=T(foot)
res={}
while True:
    h=t.b[t.i]
    if h==0: t.i+=1; break
    t.i+=1; delta=h>>4; tid=h&0xf
    res[delta]=rd(t,tid)
print(list(res.keys()))
print(res[1])
print(res[2][:1])
EOF"}

