package main

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// TypeField describes the shape of a value, mirroring the on-disk schema format.
type TypeField struct {
	Kind    string                `json:"kind"`
	Scalar  *string               `json:"scalar,omitempty"`
	Array   *TypeField            `json:"array,omitempty"`
	Object  map[string]*TypeField `json:"object,omitempty"`
	Varied  []*TypeField          `json:"varied,omitempty"`
	rawKeys []string              // original key order for object kind (marshalling only)
}

func scalarKind(k string) *TypeField {
	return &TypeField{Kind: "scalar", Scalar: &k}
}

// merge merges two type fields, keeping the first-appearance order and nesting
// varied types as observed in the reference implementation.
func merge(a, b *TypeField) *TypeField {
	if a == nil {
		return b
	}
	if sameType(a, b) {
		return a
	}
	if a.Kind == "varied" {
		for _, c := range a.Varied {
			if sameType(c, b) {
				return a
			}
		}
		return &TypeField{Kind: "varied", Varied: []*TypeField{a, b}}
	}
	if b.Kind == "varied" {
		for _, c := range b.Varied {
			if sameType(c, a) {
				return b
			}
		}
		return &TypeField{Kind: "varied", Varied: []*TypeField{b, a}}
	}
	return &TypeField{Kind: "varied", Varied: []*TypeField{a, b}}
}

func sameType(a, b *TypeField) bool {
	ab, aerr := json.Marshal(a)
	bb, berr := json.Marshal(b)
	if aerr != nil || berr != nil {
		return false
	}
	return string(ab) == string(bb)
}

func typeOfValue(v any) *TypeField {
	switch t := v.(type) {
	case nil:
		return scalarKind("null")
	case UnknownVal:
		return &TypeField{Kind: "unknown"}
	case string:
		return scalarKind("string")
	case []byte:
		return scalarKind("string")
	case int64:
		return scalarKind("number")
	case float64:
		return scalarKind("number")
	case bool:
		return scalarKind("boolean")
	default:
		_ = t
		return &TypeField{Kind: "unknown"}
	}
}

// UnknownVal is the marker used for columns absent in a row of a CSV file: it
// serialises to JSON null but shapes to the "unknown" type.
type UnknownVal struct{}

// Shape holds a table (or scalar) shape plus the data itself.
type Shape struct {
	*TypeField
	Rows  []map[string]any // rows for table-like shapes (nil for raw shapes)
	Val   any              // value for scalar/raw shapes
	Table *Table
}

// Table is an imported dataset.
type Table struct {
	Name        string
	Columns     []string
	Rows        []map[string]any
	ColTypes    map[string]*TypeField
	UnknownKeys map[string]bool
}

// Build the type field for a set of rows. Missing keys are "unknown" and null
// values are the scalar "null" kind. Keys which are missing from rows but
// present in others are appended after the scan (matching observed behavior).
func shapeFromRows(cols []string, rows []map[string]any) *TypeField {
	obj := map[string]*TypeField{}
	for _, c := range cols {
		var tf *TypeField
		var missing []bool
		missing = make([]bool, len(rows))
		had := false
		for i, r := range rows {
			if v, ok := r[c]; ok {
				had = true
				tf = merge(tf, typeOfValue(v))
			} else {
				missing[i] = true
			}
		}
		if !had {
			tf = &TypeField{Kind: "unknown"}
			// add one unknown per missing row
			for i := 0; i < len(rows); i++ {
				tf = merge(tf, &TypeField{Kind: "unknown"})
			}
		} else {
			for i := 0; i < len(rows); i++ {
				if missing[i] {
					tf = merge(tf, scalarKind("null"))
				}
			}
		}
		if tf == nil {
			tf = &TypeField{Kind: "unknown"}
		}
		obj[c] = tf
	}
	return &TypeField{Kind: "object", Object: obj}
}

// MarshalJSON implements the custom (bug-compatible) marshalling used by the
// reference implementation: object keys are embedded unescaped so a tab in a
// column name makes the resulting JSON unparseable.
func (s *Shape) MarshalJSON() ([]byte, error) {
	b, err := marshalTypeField(s.TypeField, 0, true)
	if err != nil {
		return nil, err
	}
	// Reference implementation unmarshals the manually-built JSON to verify it.
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		return nil, err
	}
	return json.MarshalIndent(v, "", "  ")
}

func marshalTypeField(t *TypeField, indent int, top bool) ([]byte, error) {
	if t == nil {
		return []byte("null"), nil
	}
	switch t.Kind {
	case "scalar":
		if t.Scalar == nil {
			return []byte(`{"kind": "scalar"}`), nil
		}
		return []byte(fmt.Sprintf("{\n%s\"kind\": \"scalar\",\n%s\"scalar\": \"%s\"\n%s}", pad(indent+1), pad(indent+1), *t.Scalar, pad(indent))), nil
	case "unknown":
		return []byte("{\n" + pad(indent+1) + "\"kind\": \"unknown\"\n" + pad(indent) + "}"), nil
	case "array":
		ab, err := marshalTypeField(t.Array, indent+1, false)
		if err != nil {
			return nil, err
		}
		return []byte(fmt.Sprintf("{\n%s\"kind\": \"array\",\n%s\"array\": %s\n%s}", pad(indent+1), pad(indent+1), string(ab), pad(indent))), nil
	case "object":
		var sb strings.Builder
		sb.WriteString("{\n" + pad(indent+1) + "\"kind\": \"object\",\n" + pad(indent+1) + "\"object\": {\n")
		keys := make([]string, 0, len(t.Object))
		for k := range t.Object {
			keys = append(keys, k)
		}
		sortStrings(keys)
		for i, k := range keys {
			// NOTE: keys are embedded raw (unescaped) - matches reference behavior.
			vb, err := marshalTypeField(t.Object[k], indent+2, false)
			if err != nil {
				return nil, err
			}
			sb.WriteString(pad(indent+2) + "\"" + k + "\": " + string(vb))
			if i != len(keys)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString(pad(indent+1) + "}\n" + pad(indent) + "}")
		return []byte(sb.String()), nil
	case "varied":
		var sb strings.Builder
		sb.WriteString("{\n" + pad(indent+1) + "\"kind\": \"varied\",\n" + pad(indent+1) + "\"varied\": [\n")
		for i, v := range t.Varied {
			vb, err := marshalTypeField(v, indent+2, false)
			if err != nil {
				return nil, err
			}
			sb.WriteString(pad(indent+2) + string(vb))
			if i != len(t.Varied)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString(pad(indent+1) + "]\n" + pad(indent) + "}")
		return []byte(sb.String()), nil
	}
	return json.Marshal(t)
}

func pad(n int) string {
	if n <= 0 {
		return ""
	}
	return strings.Repeat("  ", n)
}

func sortStrings(s []string) {
	// simple insertion sort to avoid pulling in sort package semantics differences
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// TextTree renders the shape in the "-p" human readable tree form.
func (t *TypeField) TextTree() string {
	var sb strings.Builder
	writeTree(&sb, t, 0)
	return sb.String()
}

func writeTree(sb *strings.Builder, t *TypeField, indent int) {
	p := pad(indent)
	switch t.Kind {
	case "scalar":
		sb.WriteString(p + scalarTitle(*t.Scalar) + "\n")
	case "unknown":
		sb.WriteString(p + "Unknown\n")
	case "array":
		sb.WriteString(p + "Array of\n")
		writeTree(sb, t.Array, indent+1)
	case "object":
		sb.WriteString(p + "Object of\n")
		keys := make([]string, 0, len(t.Object))
		for k := range t.Object {
			keys = append(keys, k)
		}
		sortStrings(keys)
		for _, k := range keys {
			sb.WriteString(p + "  " + k + " of\n")
			writeTree(sb, t.Object[k], indent+2)
		}
	case "varied":
		sb.WriteString(p + "Varied of\n")
		for i, v := range t.Varied {
			writeVaried(sb, v, indent+1, i == len(t.Varied)-1)
		}
	}
}

func writeVaried(sb *strings.Builder, t *TypeField, indent int, last bool) {
	p := pad(indent)
	switch t.Kind {
	case "scalar":
		sb.WriteString(p + scalarTitle(*t.Scalar))
	case "unknown":
		sb.WriteString(p + "Unknown")
	case "array":
		sb.WriteString(p + "Array of\n")
		writeVaried(sb, t.Array, indent+1, true)
	case "object":
		sb.WriteString(p + "Object of\n")
		keys := make([]string, 0, len(t.Object))
		for k := range t.Object {
			keys = append(keys, k)
		}
		sortStrings(keys)
		for i, k := range keys {
			sb.WriteString(p + "  " + k + " of\n")
			writeVaried(sb, t.Object[k], indent+2, i == len(keys)-1)
		}
	case "varied":
		sb.WriteString(p + "Varied of\n")
		for i, v := range t.Varied {
			writeVaried(sb, v, indent+1, i == len(t.Varied)-1)
		}
		return
	}
	if !last {
		sb.WriteString(" or\n")
	} else {
		sb.WriteString("\n")
	}
}

func scalarTitle(s string) string {
	switch s {
	case "string":
		return "string"
	case "number":
		return "number"
	case "boolean":
		return "boolean"
	case "null":
		return "null"
	}
	return s
}

// sqliteType maps a shape to the SQLite column type used for table creation.
func (t *TypeField) sqliteType() string {
	switch t.Kind {
	case "scalar":
		switch *t.Scalar {
		case "string":
			return "TEXT"
		case "number":
			return "REAL"
		case "boolean":
			return "BOOLEAN"
		case "null":
			return "TEXT"
		}
		return "TEXT"
	case "array", "object":
		return "TEXT"
	case "varied":
		return "TEXT"
	}
	return "TEXT"
}

// formatVariedNumber formats numbers the way the reference implementation does
// when a column contains varied types (whole floats gain a ".0" suffix).
func formatVariedNumber(f float64) string {
	s := strconv.FormatFloat(f, 'f', -1, 64)
	if !strings.Contains(s, ".") {
		s += ".0"
	}
	return s
}
