func scalarKind(k string) *TypeField {
	return &TypeField{Kind: "scalar", Scalar: &k}
}

// merge merges two type fields, keeping the first-appearance order and nesting
// varied types as observed in the reference implementation.
func merge(a, b *TypeField) *TypeField {
	if a == nil {
		return b
	}
	if sameType(a, b) {
		return a
	}
	if a.Kind == "varied" {
		for _, c := range a.Varied {
			if sameType(c, b) {
				return a
			}
		}
		return &TypeField{Kind: "varied", Varied: []*TypeField{a, b}}
	}
	if b.Kind == "varied" {
		for _, c := range b.Varied {
			if sameType(c, a) {
				return b
			}
		}
		return &TypeField{Kind: "varied", Varied: []*TypeField{b, a}}
	}
	return &TypeField{Kind: "varied", Varied: []*TypeField{a, b}}
}

func sameType(a, b *TypeField) bool {
	ab, aerr := json.Marshal(a)
	bb, berr := json.Marshal(b)
	if aerr != nil || berr != nil {
		return false
	}
	return string(ab) == string(bb)
}

func typeOfValue(v any) *TypeField {
	switch t := v.(type) {
	case nil:
		return scalarKind("null")
	case UnknownVal:
		return &TypeField{Kind: "unknown"}
	case string:
		return scalarKind("string")
	case []byte:
		return scalarKind("string")
	case int64:
		return scalarKind("number")
	case float64:
		return scalarKind("number")
	case bool:
		return scalarKind("boolean")
	default:
		_ = t
		return &TypeField{Kind: "unknown"}
	}
