// Build the type field for a set of rows. Missing keys are "unknown" and null
// values are the scalar "null" kind. Keys which are missing from rows but
// present in others are appended after the scan (matching observed behavior).
func shapeFromRows(cols []string, rows []map[string]any) *TypeField {
	obj := map[string]*TypeField{}
	for _, c := range cols {
		var tf *TypeField
		var missing []bool
		missing = make([]bool, len(rows))
		had := false
		for i, r := range rows {
			if v, ok := r[c]; ok {
				had = true
				tf = merge(tf, typeOfValue(v))
