func marshalTypeField(t *TypeField, indent int, top bool) ([]byte, error) {
	if t == nil {
		return []byte("null"), nil
	}
	switch t.Kind {
	case "scalar":
		if t.Scalar == nil {
			return []byte(`{"kind": "scalar"}`), nil
