		if err != nil {
			return nil, err
		}
		return []byte(fmt.Sprintf("{\n%s\"kind\": \"array\",\n%s\"array\": %s\n%s}", pad(indent+1), pad(indent+1), string(ab), pad(indent))), nil
	case "object":
		var sb strings.Builder
		sb.WriteString("{\n" + pad(indent+1) + "\"kind\": \"object\",\n" + pad(indent+1) + "\"object\": {\n")
		keys := make([]string, 0, len(t.Object))
		for k := range t.Object {
			keys = append(keys, k)
		}
		sortStrings(keys)
		for i, k := range keys {
			// NOTE: keys are embedded raw (unescaped) - matches reference behavior.
			vb, err := marshalTypeField(t.Object[k], indent+2, false)
			if err != nil {
				return nil, err
			}
			sb.WriteString(pad(indent+2) + "\"" + k + "\": " + string(vb))
			if i != len(keys)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString(pad(indent+1) + "}\n" + pad(indent) + "}")
		return []byte(sb.String()), nil
	case "varied":
		var sb strings.Builder
		sb.WriteString("{\n" + pad(indent+1) + "\"kind\": \"varied\",\n" + pad(indent+1) + "\"varied\": [\n")
		for i, v := range t.Varied {
			vb, err := marshalTypeField(v, indent+2, false)
			if err != nil {
				return nil, err
			}
			sb.WriteString(pad(indent+2) + string(vb))
			if i != len(t.Varied)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString(pad(indent+1) + "]\n" + pad(indent) + "}")
		return []byte(sb.String()), nil
	}
