}

func pad(n int) string {
	if n <= 0 {
		return ""
	}
	return strings.Repeat("  ", n)
}

func sortStrings(s []string) {
	// simple insertion sort to avoid pulling in sort package semantics differences
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

// TextTree renders the shape in the "-p" human readable tree form.
func (t *TypeField) TextTree() string {
	var sb strings.Builder
	writeTree(&sb, t, 0)
	return sb.String()
}

func writeTree(sb *strings.Builder, t *TypeField, indent int) {
	p := pad(indent)
	switch t.Kind {
	case "scalar":
		sb.WriteString(p + scalarTitle(*t.Scalar) + "\n")
	case "unknown":
		sb.WriteString(p + "Unknown\n")
	case "array":
		sb.WriteString(p + "Array of\n")
		writeTree(sb, t.Array, indent+1)
	case "object":
		sb.WriteString(p + "Object of\n")
		keys := make([]string, 0, len(t.Object))
		for k := range t.Object {
			keys = append(keys, k)
		}
		sortStrings(keys)
		for _, k := range keys {
			sb.WriteString(p + "  " + k + " of\n")
			writeTree(sb, t.Object[k], indent+2)
		}
	case "varied":
		sb.WriteString(p + "Varied of\n")
		for i, v := range t.Varied {
			writeVaried(sb, v, indent+1, i == len(t.Varied)-1)
		}
	}
}

func writeVaried(sb *strings.Builder, t *TypeField, indent int, last bool) {
	p := pad(indent)
	switch t.Kind {
	case "scalar":
		sb.WriteString(p + scalarTitle(*t.Scalar))
	case "unknown":
		sb.WriteString(p + "Unknown")
	case "array":
		sb.WriteString(p + "Array of\n")
		writeVaried(sb, t.Array, indent+1, true)
	case "object":
		sb.WriteString(p + "Object of\n")
		keys := make([]string, 0, len(t.Object))
		for k := range t.Object {
			keys = append(keys, k)
		}
		sortStrings(keys)
		for i, k := range keys {
			sb.WriteString(p + "  " + k + " of\n")
			writeVaried(sb, t.Object[k], indent+2, i == len(keys)-1)
