import "C"

import (
	"fmt"
	"unsafe"
)

const sqliteVersionOverride = "3.39.2"

// DB is a thin wrapper around a sqlite3 handle.
type DB struct {
	h      *C.sqlite3
	inited bool
}

func openDB(uri string) (*DB, error) {
	cu := C.CString(uri)
	defer C.free_str(cu)
	var db *C.sqlite3
	rc := C.sqlite3_open_v2(cu, &db, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_URI, nil)
	if rc != C.SQLITE_OK {
		if db != nil {
			C.sqlite3_close_v2(db)
		}
		return nil, fmt.Errorf("unable to open database file: %s", uri)
	}
	d := &DB{h: db}
	d.registerFuncs()
	return d, nil
}

func (d *DB) Close() error {
	if d.h != nil {
		C.sqlite3_close_v2(d.h)
		d.h = nil
	}
	return nil
}

func (d *DB) registerFuncs() {
	if d.inited {
		return
	}
	d.inited = true
	cn := C.CString("sqlite_version")
	defer C.free_str(cn)
	C.sqlite3_create_function(d.h, cn, 0, C.SQLITE_UTF8, nil, (*[0]byte)(C.udf_text), nil, nil)
	rn := C.CString("regexp")
	defer C.free_str(rn)
	C.sqlite3_create_function(d.h, rn, 2, C.SQLITE_UTF8, nil, (*[0]byte)(C.udf_regexp), nil, nil)
}

//export udf_text
func udf_text(ctx *C.sqlite3_context, argc C.int, argv *C.sqlite3_value) {
	s := C.CString(sqliteVersionOverride)
	defer C.free_str(s)
	C.sqlite3_result_text(ctx, s, C.int(len(sqliteVersionOverride)), C.SQLITE_TRANSIENT)
}

//export udf_regexp
func udf_regexp(ctx *C.sqlite3_context, argc C.int, argv *C.sqlite3_value) {
	if argc != 2 {
		C.sqlite3_result_error(ctx, C.CString("invalid argument count"), -1)
		return
	}
	pat := cvalText(argv, 0)
	sub := cvalText(argv, 1)
	re, err := compileRegexp(pat)
	if err != nil {
		msg := C.CString(err.Error())
		C.sqlite3_result_error(ctx, msg, C.int(len(err.Error())))
		return
	}
	m := 0
	if re.MatchString(sub) {
		m = 1
	}
	C.sqlite3_result_int(ctx, C.int(m))
}

func cvalText(argv *C.sqlite3_value, i C.int) string {
	v := (*C.sqlite3_value)(unsafe.Pointer(uintptr(unsafe.Pointer(argv)) + uintptr(i)*unsafe.Sizeof(*argv)))
	n := C.int(0)
	p := C.col_value_text(v, &n)
	if p == nil {
