	cs := C.CString(v)
	defer C.free_str(cs)
	C.bind_text_cb(s.st, C.int(i+1), cs, C.int(len(v)))
}
func (s *Stmt) BindBlob(i int, v []byte) {
	if len(v) == 0 {
		C.bind_blob_cb(s.st, C.int(i+1), nil, 0)
