	defer C.free_str(cu)
	var db *C.sqlite3
	rc := C.sqlite3_open_v2(cu, &db, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_URI, nil)
	if rc != C.SQLITE_OK {
		if db != nil {
			C.sqlite3_close_v2(db)
		}
