import "C"

import (
	"fmt"
	"unsafe"
)

const sqliteVersionOverride = "3.39.2"

// DB is a thin wrapper around a sqlite3 handle.
type DB struct {
	h      *C.sqlite3
	inited bool
}

func openDB(uri string) (*DB, error) {
	cu := C.CString(uri)
	defer C.free_str(cu)
	var db *C.sqlite3
	rc := C.sqlite3_open_v2(cu, &db, C.SQLITE_OPEN_READWRITE|C.SQLITE_OPEN_CREATE|C.SQLITE_OPEN_URI, nil)
	if rc != C.SQLITE_OK {
		if db != nil {
			C.sqlite3_close_v2(db)
		}
		return nil, fmt.Errorf("unable to open database file: %s", uri)
	}
	d := &DB{h: db}
	d.registerFuncs()
	return d, nil
}

func (d *DB) Close() error {
	if d.h != nil {
		C.sqlite3_close_v2(d.h)
		d.h = nil
	}
	return nil
}

func (d *DB) registerFuncs() {
	if d.inited {
		return
	}
	d.inited = true
	cn := C.CString("sqlite_version")
	defer C.free_str(cn)
	C.create_fn_cb(d.h, cn, 0, 0)
	rn := C.CString("regexp")
	defer C.free_str(rn)
	C.create_fn_cb(d.h, rn, 2, 1)
}

//export goUdfVersion
func goUdfVersion(ctx *C.sqlite3_context, argc C.int, argv **C.sqlite3_value) {
	s := C.CString(sqliteVersionOverride)
	defer C.free_str(s)
	C.sqlite3_result_text(ctx, s, C.int(len(sqliteVersionOverride)), C.SQLITE_TRANSIENT)
}

//export goUdfRegexp
func goUdfRegexp(ctx *C.sqlite3_context, argc C.int, argv **C.sqlite3_value) {
	pat := valText(argv, 0)
	sub := valText(argv, 1)
	re, err := compileRegexp(pat)
	if err != nil {
		msg := C.CString(err.Error())
		defer C.free_str(msg)
		C.sqlite3_result_error(ctx, msg, C.int(len(err.Error())))
		return
	}
	m := 0
	if re.MatchString(sub) {
		m = 1
	}
	C.sqlite3_result_int(ctx, C.int(m))
}

func valText(argv **C.sqlite3_value, i int) string {
	v := *(**C.sqlite3_value)(unsafe.Pointer(uintptr(unsafe.Pointer(argv)) + uintptr(i)*unsafe.Sizeof(*argv)))
	var n C.int
	p := C.val_text_cb(v, &n)
	if p == nil {
		return ""
	}
	return C.GoStringN(p, n)
}

// Exec runs a statement without results.
func (d *DB) Exec(sql string) error {
	cs := C.CString(sql)
	defer C.free_str(cs)
	rc := C.exec_cb(d.h, cs)
	if rc != C.SQLITE_OK {
		return fmt.Errorf("%s", C.GoString(C.errmsg_cb(d.h)))
	}
	return nil
}

// Rows is a result set.
type Rows struct {
	d     *DB
	st    *C.sqlite3_stmt
	Cols  []string
	Decls []string
	done  bool
	err   error
}

func (d *DB) prepare(sql string) (*C.sqlite3_stmt, error) {
	cs := C.CString(sql)
	defer C.free_str(cs)
	var st *C.sqlite3_stmt
	rc := C.prepare_cb(d.h, cs, C.int(len(sql)), &st)
	if rc != C.SQLITE_OK {
		return nil, fmt.Errorf("%s", C.GoString(C.errmsg_cb(d.h)))
	}
	return st, nil
}

func (d *DB) Query(sql string) (*Rows, error) {
	st, err := d.prepare(sql)
	if err != nil {
		return nil, err
	}
	nc := int(C.col_count_cb(st))
	cols := make([]string, nc)
	decls := make([]string, nc)
	for i := 0; i < nc; i++ {
		cols[i] = C.GoString(C.col_name_cb(st, C.int(i)))
		decls[i] = C.GoString(C.col_decl_cb(st, C.int(i)))
	}
	r := &Rows{d: d, st: st, Cols: cols, Decls: decls}
	if rc := C.step_cb(st); rc == C.SQLITE_ROW {
		return r, nil
	} else if rc == C.SQLITE_DONE {
		r.done = true
		return r, nil
	} else {
		err = fmt.Errorf("%s", C.GoString(C.errmsg_cb(d.h)))
		r.Close()
		return nil, err
	}
}

func (r *Rows) Next() bool {
	if r.done {
		return false
	}
	rc := C.step_cb(r.st)
	if rc == C.SQLITE_ROW {
		return true
	}
	r.done = true
	if rc != C.SQLITE_DONE {
		r.err = fmt.Errorf("%s", C.GoString(C.errmsg_cb(r.d.h)))
	}
	return false
}

func (r *Rows) Err() error { return r.err }

func (r *Rows) Close() error {
	if r.st != nil {
		C.sqlite3_finalize(r.st)
		r.st = nil
	}
	return nil
}

func (r *Rows) Value(i int) any {
	t := C.col_type_cb(r.st, C.int(i))
	switch t {
	case C.SQLITE_NULL:
		return nil
	case C.SQLITE_INTEGER:
		return int64(C.col_i64_cb(r.st, C.int(i)))
	case C.SQLITE_FLOAT:
		return float64(C.col_double_cb(r.st, C.int(i)))
	case C.SQLITE_TEXT:
		n := C.int(0)
		p := C.col_text_cb(r.st, C.int(i), &n)
		if p == nil {
			return ""
		}
		return C.GoStringN(p, n)
	default: // blob
		n := C.int(0)
		p := C.col_blob_cb(r.st, C.int(i), &n)
		if p == nil {
			return []byte{}
		}
		return C.GoBytes(unsafe.Pointer(p), n)
	}
}

// Stmt is a reusable prepared statement for bulk inserts.
type Stmt struct {
	d  *DB
	st *C.sqlite3_stmt
}

func (d *DB) Prepare(sql string) (*Stmt, error) {
	st, err := d.prepare(sql)
	if err != nil {
		return nil, err
	}
	return &Stmt{d: d, st: st}, nil
}

func (s *Stmt) BindNull(i int) { C.bind_null_cb(s.st, C.int(i+1)) }

func (s *Stmt) BindText(i int, v string) {
	cs := C.CString(v)
	defer C.free_str(cs)
	C.bind_text_cb(s.st, C.int(i+1), cs, C.int(len(v)))
}

func (s *Stmt) BindBlob(i int, v []byte) {
	if len(v) == 0 {
		C.bind_blob_cb(s.st, C.int(i+1), nil, 0)
		return
	}
	C.bind_blob_cb(s.st, C.int(i+1), unsafe.Pointer(&v[0]), C.int(len(v)))
}

func (s *Stmt) BindInt(i int, v int64) { C.bind_i64_cb(s.st, C.int(i+1), C.sqlite3_int64(v)) }
func (s *Stmt) BindFloat(i int, v float64) {
	C.bind_double_cb(s.st, C.int(i+1), C.double(v))
}

func (s *Stmt) Step() error {
	rc := C.step_cb(s.st)
	if rc == C.SQLITE_DONE || rc == C.SQLITE_ROW {
		C.sqlite3_reset(s.st)
		C.sqlite3_clear_bindings(s.st)
		return nil
	}
	err := fmt.Errorf("%s", C.GoString(C.errmsg_cb(s.d.h)))
	C.sqlite3_reset(s.st)
	return err
}

func (s *Stmt) Close() error {
	if s.st != nil {
		C.sqlite3_finalize(s.st)
		s.st = nil
	}
	return nil
}
