package main

// StringWidth returns the number of terminal columns used by s, following the
// common rules: zero width for control/combining characters, two columns for
// East Asian wide/fullwidth characters, one column otherwise.
func StringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += RuneWidth(r)
	}
	return w
}

func RuneWidth(r rune) int {
	if r < 0 {
		return 0
	}
	if inTable(uint32(r), zeroWidthTable[:]) {
		return 0
	}
	if inTable(uint32(r), doubleWidthTable[:]) {
		return 2
	}
	return 1
}

func inTable(r uint32, t []rng) bool {
	lo, hi := 0, len(t)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		if r < t[mid].lo {
			hi = mid - 1
		} else if r > t[mid].hi {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}
