// Mimetype identifiers used internally.
const (
	mtCSV     = "text/csv"
	mtTSV     = "text/tab-separated-values"
	mtJSON    = "application/json"
	mtNDJSON  = "application/jsonlines"
	mtText    = "text/plain"
	mtXLSX    = "application/vnd.ms-excel"
	mtODS     = "application/vnd.oasis.opendocument.spreadsheet"
	mtParquet = "application/parquet"
	mtAvro    = "application/avro"
	mtORC     = "application/x-orc"
)

type importer int

const (
	impCSV importer = iota
	impTSV
	impJSON
	impNDJSON
	impText
	impXLSX
	impODS
	impParquet
	impAvro
	impORC
)

var extToImp = map[string]importer{
	"csv":     impCSV,
	"tsv":     impTSV,
	"json":    impJSON,
	"ndjson":  impNDJSON,
	"jsonl":   impNDJSON,
	"txt":     impText,
	"yaml":    impText,
	"yml":     impText,
	"xlsx":    impXLSX,
	"xls":     impXLSX,
	"ods":     impODS,
	"parquet": impParquet,
	"avro":    impAvro,
	"orc":     impORC,
}

var mtToImp = map[string]importer{
	mtCSV:     impCSV,
	mtTSV:     impTSV,
	mtJSON:    impJSON,
	mtNDJSON:  impNDJSON,
	mtText:    impText,
	mtXLSX:    impXLSX,
	mtODS:     impODS,
	mtParquet: impParquet,
	mtAvro:    impAvro,
	mtORC:     impORC,
	// Mimetypes that fall back to the plain-text (JSON) importer.
	"text/yaml": impText,
}

func impForExt(ext string) (importer, bool) {
	i, ok := extToImp[strings.TrimPrefix(ext, ".")]
	return i, ok
}

// importForString resolves a -s argument: bare names are treated as file
// extensions, names with a slash as mimetypes (unknown ones fall back to the
// plain text importer, mirroring the reference implementation).
func impForString(s string) (importer, bool) {
	if strings.Contains(s, "/") {
		if i, ok := mtToImp[s]; ok {
			return i, true
		}
		return impText, true
	}
	return impForExt(s)
}

// Input describes one data source.
type Input struct {
	Path    string // path on disk (or temp file for stdin)
	Name    string // display name
	Data    []byte
	Imp     importer
