	if i := strings.LastIndexByte(p, '.'); i >= 0 {
		ext = p[i+1:]
	}
	imp, ok := impForExt(ext)
	if !ok {
		return nil, fmt.Errorf("Unknown mimetype for file: %s.", p)
	}
	return &Input{Path: p, Name: p, Data: data, Imp: imp}, nil
}

// shapeOpts carries import-time options.
type shapeOpts struct {
	Numbers bool // -n: convert numeric-looking strings
}

// ShapeFromInput parses the input and computes its shape and rows.
func ShapeFromInput(in *Input, o *shapeOpts) (*Shape, error) {
	switch in.Imp {
	case impCSV:
		return importCSV(in, o, ',')
	case impTSV:
		return importCSV(in, o, '\t')
	case impJSON:
		return importJSON(in, o, true)
	case impNDJSON:
		return importJSON(in, o, false)
	case impText:
		return importText(in, o)
	case impXLSX:
		return importXLSX(in, o)
	case impODS:
		return importODS(in, o)
	case impParquet:
		return importParquet(in, o)
	case impAvro:
		return importAvro(in, o)
	case impORC:
		return importORC(in, o)
	}
	return nil, fmt.Errorf("Unknown mimetype for file: %s.", in.Path)
}

// importCSV handles both CSV and TSV.
func importCSV(in *Input, o *shapeOpts, comma rune) (*Shape, error) {
	r := csv.NewReader(bytes.NewReader(in.Data))
	r.FieldsPerRecord = -1
	r.Comma = comma
	records, err := r.ReadAll()
	if err != nil {
		return nil, err
	}
	t := &Table{ColTypes: map[string]*TypeField{}, UnknownKeys: map[string]bool{}}
	if len(records) == 0 {
		return &Shape{TypeField: &TypeField{Kind: "array", Array: &TypeField{Kind: "unknown"}}, Table: t}, nil
	}
	header := records[0]
	cols := []string{}
	seen := map[string]bool{}
	nameFor := func(i int, hdr []string) string {
		if i < len(hdr) && hdr[i] != "" {
			return hdr[i]
		}
		return colLetter(i)
	}
	// header columns
	for i := range header {
		nm := nameFor(i, header)
		if !seen[nm] {
			seen[nm] = true
			cols = append(cols, nm)
		}
	}
	rows := make([]map[string]any, 0, len(records)-1)
	for _, rec := range records[1:] {
		m := map[string]any{}
		n := len(header)
		if len(rec) > n {
			n = len(rec)
		}
		for i := 0; i < n; i++ {
			var v any
			if i < len(rec) {
				s := rec[i]
				if o.Numbers {
					v = parseNumber(s)
				} else {
					v = s
				}
			} else {
				v = UnknownVal{}
			}
			nm := ""
			if i < len(header) {
				nm = nameFor(i, header)
			} else {
				nm = colLetter(i)
			}
			m[nm] = v
			if !seen[nm] {
				seen[nm] = true
				cols = append(cols, nm)
			}
		}
		rows = append(rows, m)
	}
	t.Columns = cols
	t.Rows = rows
	sh := shapeFromRows(cols, rows)
	return &Shape{TypeField: &TypeField{Kind: "array", Array: sh}, Rows: rows, Table: t}, nil
}

func colLetter(i int) string {
	return string(rune('A' + rune(i%26) + rune(i/26)*0))
}

// parseNumber converts a string that looks like a number into an int64/float64.
func parseNumber(s string) any {
	t := strings.TrimSpace(s)
	if t == "" {
		return s
	}
	if i, err := strconv.ParseInt(t, 10, 64); err == nil {
		return i
	}
	if f, err := strconv.ParseFloat(t, 64); err == nil {
		return f
	}
	return s
}

// RawVal wraps raw JSON bytes so they are written verbatim in output.
type RawVal []byte

// importText treats the whole input as a single string value.
func importText(in *Input, o *shapeOpts) (*Shape, error) {
	return &Shape{TypeField: scalarKind("string"), Val: string(in.Data)}, nil
}

// importJSON handles both single-document JSON and newline delimited JSON.
// single=true means application/json: rows come from the first top-level
// value when it is an array of objects.
func importJSON(in *Input, o *shapeOpts, single bool) (*Shape, error) {
	dec := json.NewDecoder(bytes.NewReader(in.Data))
	dec.UseNumber()
	var vals []any
	first := true
	var firstVal any
	for {
		var v any
		if err := dec.Decode(&v); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}
		if first {
			first = false
			firstVal = v
		}
		vals = append(vals, v)
		if single {
			break
		}
	}
	var sh *TypeField
	if single {
		sh = shapeOfJSON(firstVal)
	} else {
		var et *TypeField
		for _, v := range vals {
			et = merge(et, shapeOfJSON(v))
		}
		if et == nil {
			et = &TypeField{Kind: "unknown"}
		}
		sh = &TypeField{Kind: "array", Array: et}
	}
	s := &Shape{TypeField: sh, Table: &Table{ColTypes: map[string]*TypeField{}, UnknownKeys: map[string]bool{}}}
	if single {
		s.Raw = in.Data
		if arr, ok := firstVal.([]any); ok {
			rows := make([]map[string]any, 0, len(arr))
			cols := []string{}
			seen := map[string]bool{}
			ok2 := true
			for _, e := range arr {
				m, isObj := e.(map[string]any)
				if !isObj {
					ok2 = false
					break
				}
				rm := map[string]any{}
				for k, v := range m {
					rm[k] = jsonVal(v)
					if !seen[k] {
						seen[k] = true
						cols = append(cols, k)
					}
				}
				rows = append(rows, rm)
			}
			if ok2 {
				s.Rows = rows
				s.Table.Columns = cols
				s.Table.Rows = rows
			}
		}
	} else {
		rows := make([]map[string]any, 0, len(vals))
		cols := []string{}
		seen := map[string]bool{}
		ok2 := true
		for _, v := range vals {
			m, isObj := v.(map[string]any)
			if !isObj {
				ok2 = false
				break
			}
			rm := map[string]any{}
			for k, vv := range m {
				rm[k] = jsonVal(vv)
				if !seen[k] {
					seen[k] = true
					cols = append(cols, k)
				}
			}
			rows = append(rows, rm)
		}
		if ok2 {
			s.Rows = rows
			s.Table.Columns = cols
			s.Table.Rows = rows
		}
	}
	return s, nil
}

// jsonVal converts a decoded JSON value into our internal representation:
// nested containers keep their raw JSON bytes.
func jsonVal(v any) any {
	switch t := v.(type) {
	case nil:
		return nil
	case bool:
		return t
	case string:
		return t
	case json.Number:
		f, err := t.Float64()
		if err != nil {
			return t.String()
		}
		return f
	case []any:
		return RawVal(compactJSON(v))
	case map[string]any:
		return RawVal(compactJSON(v))
	}
	return v
}

func compactJSON(v any) []byte {
	b, err := json.Marshal(v)
	if err != nil {
		return []byte("null")
	}
	return b
}

// shapeOfJSON computes the type field for a decoded JSON value.
func shapeOfJSON(v any) *TypeField {
	switch t := v.(type) {
	case nil:
		return scalarKind("null")
	case bool:
		return scalarKind("boolean")
	case string:
		return scalarKind("string")
	case json.Number:
		return scalarKind("number")
	case []any:
		var et *TypeField
		for _, e := range t {
			et = merge(et, shapeOfJSON(e))
		}
		if et == nil {
			et = &TypeField{Kind: "unknown"}
		}
		return &TypeField{Kind: "array", Array: et}
	case map[string]any:
		obj := map[string]*TypeField{}
		for k, vv := range t {
			obj[k] = shapeOfJSON(vv)
		}
		return &TypeField{Kind: "object", Object: obj}
	}
	return &TypeField{Kind: "unknown"}
}

// Compile a regexp for the SQL regexp() UDF.
func compileRegexp(pat string) (regexpLike, error) {
	return compileRegexpImpl(pat)
}

type regexpLike interface {
	MatchString(string) bool
}

var _ = flate.NewWriter
var _ = time.Now
EOF
