{"command": "cd /workspace && cat > result.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// Writer renders query/import results.
type Writer interface {
	WriteRows(rows []map[string]any) error
	WriteValues(vals []any) error
}

type jsonWriter struct{ w io.Writer }

// NewJSONWriter returns the default (JSON array) result writer.
func NewJSONWriter(w io.Writer) Writer { return &jsonWriter{w: w} }

func (j *jsonWriter) WriteRows(rows []map[string]any) error {
	return writeJSONList(j.w, rows, true)
}

func (j *jsonWriter) WriteValues(vals []any) error {
	return writeJSONList(j.w, vals, false)
}

// writeJSONList writes "[" elements joined with ",\n" "]" and a trailing newline.
func writeJSONList(w io.Writer, items []any, asMaps bool) error {
	var sb strings.Builder
	sb.WriteString("[")
	for i, it := range items {
		if i > 0 {
			sb.WriteString(",\n")
		}
		b, err := marshalValue(it)
		if err != nil {
			return err
		}
		sb.Write(b)
	}
	sb.WriteString("]\n")
	_, err := io.WriteString(w, sb.String())
	return err
}

// marshalValue marshals a single output value with Go's JSON encoder rules.
func marshalValue(v any) ([]byte, error) {
	switch t := v.(type) {
	case nil:
		return []byte("null"), nil
	case RawVal:
		return []byte(t), nil
	case []byte:
		return []byte(t), nil
	case json.Number:
		return []byte(string(t)), nil
	case map[string]any:
		return marshalObject(t)
	case []any:
		return writeJSONListBytes(t)
	}
	return json.Marshal(v)
}

func writeJSONListBytes(items []any) ([]byte, error) {
	var sb strings.Builder
	sb.WriteString("[")
	for i, it := range items {
		if i > 0 {
			sb.WriteString(",\n")
		}
		b, err := marshalValue(it)
		if err != nil {
			return nil, err
		}
		sb.Write(b)
	}
	sb.WriteString("]")
	return []byte(sb.String()), nil
}

// marshalObject writes an object preserving insertion order of the given keys.
func marshalObject(m map[string]any) ([]byte, error) {
	keys := m["__keys__"].([]string)
	var sb strings.Builder
	sb.WriteString("{")
	for i, k := range keys {
		if i > 0 {
			sb.WriteString(",")
		}
		kb, err := json.Marshal(k)
		if err != nil {
			return nil, err
		}
		sb.Write(kb)
		sb.WriteString(":")
		b, err := marshalValue(m[k])
		if err != nil {
			return nil, err
		}
		sb.Write(b)
	}
	sb.WriteString("}")
	return []byte(sb.String()), nil
}

// orderedRow is a row that remembers its key order for JSON output.
type orderedRow struct {
	keys []string
	vals map[string]any
}

func rowForOutput(keys []string, vals map[string]any) map[string]any {
	m := map[string]any{}
	for _, k := range keys {
		m[k] = vals[k]
	}
	// stash the key order using an unexported-style key that never collides
	// because SQLite column names cannot contain this token
	m["\x00keys"] = keys
	return m
}

// prettyWriter renders ASCII tables.
type prettyWriter struct{ w io.Writer }

// NewPrettyWriter returns the table (pretty) result writer.
func NewPrettyWriter(w io.Writer) Writer { return &prettyWriter{w: w} }

func (p *prettyWriter) WriteRows(rows []map[string]any) error {
	return p.writeTable(rows)
}

func (p *prettyWriter) WriteValues(vals []any) error {
	// Not reachable in practice: the pretty writer only handles tabular data.
	return p.writeTable(nil)
}

// cellLines splits a value into its display lines.
func cellLines(v any) []string {
	s := valueString(v)
	return strings.Split(s, "\n")
}

// valueString renders a value for display.
func valueString(v any) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case RawVal:
		return string(t)
	case []byte:
		return string(t)
	case bool:
		if t {
			return "true"
		}
		return "false"
	case int64:
		return strconv.FormatInt(t, 10)
	case float64:
		return strconv.FormatFloat(t, 'f', -1, 64)
	case json.Number:
		return string(t)
	case string:
		return t
	}
	return fmt.Sprintf("%v", v)
}

// isNumericValue reports whether the value should be right aligned.
func isNumericValue(v any) bool {
	switch t := v.(type) {
	case int64, float64:
		return true
	case json.Number:
		_, err := strconv.ParseFloat(string(t), 64)
		return err == nil
	case string:
		if t == "" {
			return false
		}
		if _, err := strconv.ParseFloat(strings.TrimSpace(t), 64); err == nil {
			return true
		}
		return false
	}
	return false
}

func (p *prettyWriter) writeTable(rows []map[string]any) error {
	if len(rows) == 0 {
		// The reference implementation dereferences a nil writer here.
		var np *prettyWriter
		_ = np.writeTable(nil)
	}
	// collect column order (sorted)
	colSet := map[string]bool{}
	for _, r := range rows {
		for k := range r {
			if k == "\x00keys" {
				continue
			}
			colSet[k] = true
		}
	}
	cols := make([]string, 0, len(colSet))
	for k := range colSet {
		cols = append(cols, k)
	}
	sortStrings(cols)
	// compute widths
	widths := make([]int, len(cols))
	for i, c := range cols {
		w := StringWidth(c)
		for _, r := range rows {
			for _, ln := range cellLines(r[c]) {
				if lw := StringWidth(ln); lw > w {
					w = lw
				}
			}
		}
		widths[i] = w
	}
	var sb strings.Builder
	// border
	sb.WriteString(sepLine(widths))
	sb.WriteString("\n")
	// header
	sb.WriteString("|")
	for i, c := range cols {
		sb.WriteString(" " + center(c, widths[i]) + " |")
	}
	sb.WriteString("\n")
	sb.WriteString(sepLine(widths))
	sb.WriteString("\n")
	// rows: split into display lines
	type rowLines struct {
		lines [][]string
		nums  []bool
	}
	maxLines := 1
	rl := make([]rowLines, len(rows))
	for ri, r := range rows {
		ls := make([][]string, len(cols))
		ns := make([]bool, len(cols))
		for ci, c := range cols {
			v := r[c]
			ls[ci] = cellLines(v)
			ns[ci] = isNumericValue(v)
			if len(ls[ci]) > maxLines {
				maxLines = len(ls[ci])
			}
		}
		rl[ri] = rowLines{lines: ls, nums: ns}
	}
	for _, r := range rl {
		for li := 0; li < maxLines; li++ {
			sb.WriteString("|")
			for ci := range cols {
				var txt string
				if li < len(r.lines[ci]) {
					txt = r.lines[ci][li]
				}
				w := widths[ci]
				if li >= len(r.lines[ci]) && w < 2 {
					w = 2
				}
				if r.nums[ci] {
					txt = leftPad(txt, w)
				} else {
					txt = rightPad(txt, w)
				}
				sb.WriteString(" " + txt + " |")
			}
			sb.WriteString("\n")
		}
	}
	sb.WriteString(sepLine(widths))
	sb.WriteString("\n")
	noun := "rows"
	if len(rows) == 1 {
		noun = "row"
	}
	sb.WriteString(fmt.Sprintf("(%d %s)\n", len(rows), noun))
	_, err := io.WriteString(p.w, sb.String())
	return err
}

func sepLine(widths []int) string {
	var sb strings.Builder
	sb.WriteString("+")
	for _, w := range widths {
		sb.WriteString(strings.Repeat("-", w+2))
		sb.WriteString("+")
	}
	return sb.String()
}

func center(s string, w int) string {
	pad := w - StringWidth(s)
	if pad <= 0 {
		return s
	}
	l := pad / 2
	r := pad - l
	return strings.Repeat(" ", l) + s + strings.Repeat(" ", r)
}

func leftPad(s string, w int) string {
	p := w - StringWidth(s)
	if p <= 0 {
		return s
	}
	return strings.Repeat(" ", p) + s
}

func rightPad(s string, w int) string {
	p := w - StringWidth(s)
	if p <= 0 {
		return s
	}
	return s + strings.Repeat(" ", p)
}

// MarshalShape writes the schema in the requested format.
func MarshalShape(t *TypeField, pretty bool) (string, error) {
	if pretty {
		return t.TextTree(), nil
	}
	s := &Shape{TypeField: t}
	b, err := s.MarshalJSON()
	if err != nil {
		return "", err
	}
	return string(b), nil
}

var _ = strconv.Itoa
EOF
echo ok"}

