func shapeFromRows(t *Table, rows []Row) *TypeField {
	obj := map[string]*TypeField{}
	for _, c := range t.Columns {
		var tf *TypeField
		seen := false
		seenLens := map[int]bool{}
		for _, r := range rows {
			if r.Has(c) {
				seen = true
				tf = merge(tf, typeOfValue(r.Get(c)))
			}
		}
		for _, r := range rows {
			if r.Has(c) {
				continue
			}
			if t.ExtraCols[c] && r.NFields < t.HeaderLen {
				tf = merge(tf, scalarKind("null"))
				continue
			}
			if !seenLens[r.NFields] {
				seenLens[r.NFields] = true
				tf = merge(tf, &TypeField{Kind: "unknown"})
			}
		}
		if tf == nil {
			tf = &TypeField{Kind: "unknown"}
		}
		obj[c] = tf
	}
	return &TypeField{Kind: "object", Object: obj}
}

