{"command": "cd /workspace && cat > main.go <<'EOF'
package main

import (
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"math/rand"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const helpText = `dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq
`

// config holds the parsed command line.
type config struct {
	pretty      bool
	schema      bool
	cache       bool
	debug       bool
	interactive bool
	numbers     bool
	stdinImp    importer
	hasStdin    bool
	sqlFile     string
	files       []string
	query       string
}

func parseArgs(args []string) (*config, error) {
	c := &config{}
	var rest []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		switch a {
		case "-p", "--pretty":
			c.pretty = true
		case "-s":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("Must specify stdin mimetype.")
			}
			i++
			mt := args[i]
			imp, ok := impForString(mt)
			if !ok {
				// resolved later against the temp file name
				c.stdinImp = -1
				c.stdinName = mt
				c.hasStdin = true
				continue
			}
			c.stdinImp = imp
			c.hasStdin = true
		case "-f", "--file":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("Must specify a SQL file.")
			}
			i++
			c.sqlFile = args[i]
		case "--schema", "-c":
			c.schema = true
		case "-C", "--cache":
			c.cache = true
		case "-i", "--interactive":
			c.interactive = true
		case "-D":
			c.debug = true
		case "-n":
			c.numbers = true
		case "-h", "--help":
			fmt.Fprint(os.Stderr, helpText)
			os.Exit(0)
		case "-v", "--version":
			fmt.Fprintln(os.Stderr, "dsq latest")
			os.Exit(0)
		default:
			rest = append(rest, a)
		}
	}
	if c.sqlFile != "" {
		c.files = rest
	} else if c.hasStdin && len(rest) > 0 {
		c.files = rest[:len(rest)-1]
		c.query = rest[len(rest)-1]
	} else if len(rest) > 1 {
		c.files = rest[:len(rest)-1]
		c.query = rest[len(rest)-1]
	} else {
		c.files = rest
	}
	if c.sqlFile != "" {
		b, err := os.ReadFile(c.sqlFile)
		if err != nil {
			return nil, fmt.Errorf("Error opening sql file: %v", err)
		}
		c.query = strings.TrimRight(string(b), "\n")
	}
	return c, nil
}

func fail(err error) int {
	fmt.Fprintln(os.Stderr, err.Error())
	return 1
}

func main() {
	os.Exit(_main())
}

func _main() int {
	cfg, err := parseArgs(os.Args[1:])
	if err != nil {
		return fail(err)
	}
	var inputs []*Input
	if cfg.hasStdin {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return fail(err)
		}
		tmp := tempStdinName()
		if err := os.WriteFile(tmp, data, 0600); err != nil {
			return fail(err)
		}
		defer os.Remove(tmp)
