// rewriteQuery replaces {N} and {} with quoted table names.
func rewriteQuery(q string, n int) (string, error) {
	var sb strings.Builder
	i := 0
	for i < len(q) {
		c := q[i]
		if c == '{' {
			j := strings.IndexByte(q[i:], '}')
			if j > 0 {
				inner := q[i+1 : i+j]
				if inner == "" {
					idx := 0
					if idx >= n {
						panicIndex(idx, n)
					}
					sb.WriteString(fmt.Sprintf("%q", fmt.Sprintf("t_%d", idx)))
					i += j + 1
					continue
				}
				if num, err := strconv.Atoi(inner); err == nil && num >= 0 && inner == strconv.Itoa(num) {
					if num >= n {
						panicIndex(num, n)
					}
					sb.WriteString(fmt.Sprintf("%q", fmt.Sprintf("t_%d", num)))
					i += j + 1
					continue
				}
			}
		}
		sb.WriteByte(c)
		i++
	}
	return sb.String(), nil
}

func panicIndex(idx, n int) {
	// Reproduce the reference implementation's index panic.
	var s []int
	_ = s[idx]
	_ = n
}

// importAll creates the tables for all CSV-like inputs (used at startup and on
// each interactive statement).
func importAll(db *DB, shapes []*Shape) error {
	for i, sh := range shapes {
		if sh.Table == nil || len(sh.Table.Rows) == 0 {
			continue
		}
		if sh.impKind != impCSV && sh.impKind != impTSV {
			continue
		}
		if err := ensureTable(db, i, sh); err != nil {
			return err
		}
	}
	return nil
}

// lazily import a single table when a query references it
func ensureReferenced(db *DB, shapes []*Shape, q string) error {
	for i := 0; i < len(shapes); i++ {
		if !strings.Contains(q, "{"+strconv.Itoa(i)+"}") && !strings.Contains(q, "{}") {
			continue
		}
		sh := shapes[i]
		if sh.Rows == nil {
			continue
		}
		if sh.impKind == impCSV || sh.impKind == impTSV {
			continue // already created
		}
		if err := ensureTable(db, i, sh); err != nil {
			return err
		}
	}
	return nil
}

// convertResult converts a SQLite value for output.
func convertResult(v any, decl string) any {
	if strings.EqualFold(decl, "BOOLEAN") {
		switch t := v.(type) {
		case int64:
			return t != 0
		case nil:
			return nil
		}
	}
	switch t := v.(type) {
	case []byte:
		return string(t)
	}
	return v
}

// shapeOfResult computes the shape of a query result.
func shapeOfResult(rows [][]any, cols []string, decls []string) *TypeField {
	obj := map[string]*TypeField{}
	for ci, c := range cols {
		var tf *TypeField
		seenStr := false
		for ri := range rows {
			v := convertResult(rows[ri][ci], decls[ci])
			if _, ok := v.(string); ok {
				seenStr = true
			}
			tf = merge(tf, typeOfValue(v))
		}
		if tf == nil {
			tf = &TypeField{Kind: "unknown"}
		} else if len(rows) > 0 {
			last := convertResult(rows[len(rows)-1][ci], decls[ci])
			if _, ok := last.(string); ok {
				tf = scalarKind("string")
			}
		}
		_ = seenStr
		obj[c] = tf
	}
	return &TypeField{Kind: "object", Object: obj}
}

// runQueryPath executes the query and writes the result.
func runQueryPath(cfg *config, db *DB, shapes []*Shape, query string) int {
	if err := ensureReferenced(db, shapes, query); err != nil {
		return fail(err)
	}
	rq, err := rewriteQuery(query, len(shapes))
	if err != nil {
		return fail(err)
	}
	r, err := db.Query(rq)
	if err != nil {
		return fail(err)
	}
	defer r.Close()
	var rows [][]any
	for r.Next() {
		row := make([]any, len(r.Cols))
		for i := range r.Cols {
			row[i] = r.Value(i)
		}
		rows = append(rows, row)
	}
	if r.Err() != nil {
		return fail(r.Err())
	}
	if cfg.schema {
		sh := shapeOfResult(rows, r.Cols, r.Decls)
		s := &Shape{TypeField: &TypeField{Kind: "array", Array: sh}}
		return printShape(cfg, s.TypeField)
	}
	// build output rows
	out := make([]Row, 0, len(rows))
	for _, rv := range rows {
		vals := map[string]any{}
		for i, c := range r.Cols {
			vals[c] = convertResult(rv[i], r.Decls[i])
		}
		out = append(out, Row{Keys: append([]string{}, r.Cols...), Vals: vals})
	}
	var w Writer
	if cfg.pretty {
		w = NewPrettyWriter(os.Stdout)
	} else {
		w = NewJSONWriter(os.Stdout)
	}
	if err := w.WriteRows(out); err != nil {
		return fail(err)
	}
	return 0
}

// printShape writes the schema (JSON or text tree depending on -p).
func printShape(cfg *config, tf *TypeField) int {
	s, err := MarshalShape(tf, cfg.pretty)
	if err != nil {
		return fail(err)
	}
	fmt.Fprintln(os.Stdout, s)
	return 0
}

// runSchema handles the --schema flag.
func runSchema(cfg *config, db *DB, shapes []*Shape) int {
	if cfg.query != "" {
		return runQueryPath(cfg, db, shapes, cfg.query)
	}
	return printShape(cfg, shapes[0].TypeField)
}

// dumpInput writes the imported shape of a single input.
func dumpInput(cfg *config, in *Input, sh *Shape) int {
	if in.Imp == impJSON {
		// echo the raw bytes, panicking under -p like the reference build
		if cfg.pretty {
			prettyNilPanic()
		}
		fmt.Println(string(sh.Raw))
		return 0
	}
	if in.Imp == impText {
		if cfg.pretty {
			prettyNilPanic()
		}
		b, err := json.Marshal(sh.Val)
		if err != nil {
			return fail(err)
		}
		fmt.Println(string(b))
		return 0
	}
	var w Writer
	if cfg.pretty {
		w = NewPrettyWriter(os.Stdout)
	} else {
		w = NewJSONWriter(os.Stdout)
	}
	out := make([]Row, 0, len(sh.Rows))
	for _, r := range sh.Rows {
		out = append(out, r)
	}
	if err := w.WriteRows(out); err != nil {
		return fail(err)
	}
	return 0
}

// prettyNilPanic emulates the nil dereference the reference build performs
// when the pretty writer is handed a non-tabular result.
func prettyNilPanic() {
	var p *prettyWriter
	_ = p.writeTable(nil)
}

// repl implements the -i interactive loop.
func repl(cfg *config, db *DB, shapes []*Shape) int {
	r := newLineReader(os.Stdin)
	for {
		line, err := r.readLine()
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			return 1
		}
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if err := importAll(db, shapes); err != nil {
			return fail(err)
		}
		if rc := runQueryPath(cfg, db, shapes, trimmed); rc != 0 {
			return rc
		}
	}
}
