func newLineReader(r io.Reader) *lineReader { return &lineReader{r: bufio.NewReader(r)} }

func (l *lineReader) readLine() (string, error) {
	s, err := l.r.ReadString('\n')
	if err != nil {
		if len(s) == 0 {
			return "", io.EOF
		}
		return s, err
	}
	return trimNewline(s), nil
}

