// prettyNilPanic emulates the nil dereference the reference build performs
// when the pretty writer is handed a non-tabular result.
func prettyNilPanic() {
	var p *prettyWriter
	_ = p.writeTable(nil)
}

// repl implements the -i interactive loop.
func repl(cfg *config, db *DB, shapes []*Shape) int {
	r := newLineReader(os.Stdin)
	for {
		line, err := r.readLine()
		if err != nil {
			fmt.Fprintln(os.Stderr, err.Error())
			return 1
		}
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		if err := importAll(db, shapes); err != nil {
			return fail(err)
		}
		if rc := runQueryPath(cfg, db, shapes, trimmed); rc != 0 {
			return rc
		}
	}
}
