type colDef struct {
	name string
	typ  string
	path []string // path of keys into a nested object for flattened columns
}

// columnsFromShape derives the SQLite column definitions from a table shape.
func columnsFromShape(obj *TypeField) []colDef {
	var out []colDef
	var walk func(prefix []string, tf *TypeField)
	walk = func(prefix []string, tf *TypeField) {
		if tf == nil {
			out = append(out, colDef{name: strings.Join(prefix, "."), typ: "TEXT"})
			return
		}
		if tf.Kind == "object" && len(prefix) < 8 {
			keys := make([]string, 0, len(tf.Object))
			for k := range tf.Object {
				keys = append(keys, k)
			}
			for _, k := range keys {
				walk(append(append([]string{}, prefix...), k), tf.Object[k])
			}
			return
		}
		out = append(out, colDef{name: strings.Join(prefix, "."), typ: tf.sqliteType()})
	}
	walk(nil, obj)
	return out
}

// tableRows prepares rows for insertion: flattened columns are extracted from
// the raw JSON of nested objects.
func tableRows(sh *Shape) ([]Row, []colDef) {
	obj := sh.TypeField.Array
	if obj == nil {
		obj = sh.TypeField
	}
	defs := columnsFromShape(obj)
	if sh.Table != nil && len(sh.Table.Rows) > 0 {
		return sh.Table.Rows, defs
	}
	return nil, defs
}

// ensureTable creates the table and inserts rows.
func ensureTable(db *DB, idx int, sh *Shape) error {
	name := fmt.Sprintf("t_%d", idx)
	rows, defs := tableRows(sh)
	if defs == nil {
		return nil
	}
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("CREATE TABLE %q(", name))
	for i, d := range defs {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString(fmt.Sprintf("%q %s", d.name, d.typ))
	}
	sb.WriteString(")")
	if err := db.Exec(sb.String()); err != nil {
		return err
	}
	if len(rows) == 0 {
		return nil
	}
	var ins strings.Builder
	ins.WriteString(fmt.Sprintf("INSERT INTO %q (", name))
	for i, d := range defs {
		if i > 0 {
			ins.WriteString(", ")
		}
		ins.WriteString(fmt.Sprintf("%q", d.name))
	}
	ins.WriteString(") VALUES (")
	for i := range defs {
		if i > 0 {
			ins.WriteString(", ")
		}
		ins.WriteString("?")
	}
	ins.WriteString(")")
	st, err := db.Prepare(ins.String())
	if err != nil {
		return err
	}
	defer st.Close()
	for _, r := range rows {
		for i, d := range defs {
			v := leafValue(r, d)
			bindColumn(st, i, v, d)
		}
		if err := st.Step(); err != nil {
			return err
