	if len(d.path) == 0 {
		return r.Get(d.name)
	}
	// walk into nested raw JSON
	var cur any = r.Get(d.path[0])
	for i := 1; i < len(d.path); i++ {
		b, ok := cur.([]byte)
		if !ok {
			rv, ok2 := cur.(RawVal)
			if !ok2 {
				return nil
			}
			b = []byte(rv)
		}
		var m map[string]any
		if err := json.Unmarshal(b, &m); err != nil {
			return nil
