func importXLSX(in *Input, o *shapeOpts) (*Shape, error) {
	zr, err := zip.NewReader(bytes.NewReader(in.Data), int64(len(in.Data)))
	if err != nil {
		return nil, err
	}
	return readWorkbook(zr, in, o, false)
}

// importODS reads an OpenDocument spreadsheet, wrapping errors like the
// reference implementation does.
func importODS(in *Input, o *shapeOpts) (*Shape, error) {
	zr, err := zip.NewReader(bytes.NewReader(in.Data), int64(len(in.Data)))
	if err != nil {
		return nil, makeErrException(err)
	}
	sh, err := readODS(zr, in, o)
	if err != nil {
		if de, ok := err.(*DSError); ok {
			return nil, de
		}
		return nil, makeErrException(err)
	}
	return sh, nil
}

// importAvro reads an Object Container File; only the error path for invalid
// magic bytes is reproduced faithfully here.
func importAvro(in *Input, o *shapeOpts) (*Shape, error) {
	if len(in.Data) < 4 || !bytes.Equal(in.Data[:4], []byte("Obj\x01")) {
		return nil, fmt.Errorf("cannot create OCFReader: cannot read OCF header with invalid magic bytes: %s", quoteMagic(in.Data))
	}
	return nil, errors.New("avro: unsupported")
}

func quoteMagic(data []byte) string {
	if len(data) < 4 {
		if len(data) == 0 {
			return `""`
		}
		return strconv.Quote(string(data))
	}
	if !isPrintable(data[:4]) {
		return "`" + string(data[:4]) + "`"
	}
	return strconv.Quote(string(data[:4]))
}

func isPrintable(b []byte) bool {
	for _, c := range b {
		if c < 0x20 || c > 0x7e {
			return false
		}
	}
	return true
}

// importORC reproduces the slice-bounds panic of the reference build for
// malformed files.
func importORC(in *Input, o *shapeOpts) (*Shape, error) {
	n := len(in.Data)
	// The reference implementation slices the footer using the postscript
	// length read from the final byte.
	psLen := 0
	if n > 0 {
		psLen = int(in.Data[n-1])
	}
	_ = in.Data[n-11:]
	_ = psLen
	panicIndex(n-11, 0)
	return nil, nil
}

// importParquet reads a Parquet file footer.
func importParquet(in *Input, o *shapeOpts) (*Shape, error) {
	f, err := os.Open(in.Path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		return nil, err
	}
	size := st.Size()
	if size < 8 {
		if _, err := f.Seek(size-8, 0); err != nil {
			return nil, err
		}
	}
	buf := make([]byte, 8)
	if _, err := f.ReadAt(buf, size-8); err != nil {
		return nil, err
	}
	if string(buf[4:]) != "PAR1" {
		return nil, errors.New("parquet: invalid footer")
	}
	mlen := int64(binary.LittleEndian.Uint32(buf[:4]))
	if mlen > size-12 {
		return nil, errors.New("parquet: invalid footer length")
	}
	foot := make([]byte, mlen)
	if _, err := f.ReadAt(foot, size-8-mlen); err != nil {
		return nil, err
	}
	return readParquet(in, foot)
}
