{"command": "cd /workspace && cat > orderedjson.go <<'EOF'
package main

// An ordered JSON scanner: it produces the same scalar values as encoding/json
// (json.Number for numbers) but remembers object key order and keeps the raw
// byte slices of containers, which the reference implementation echoes back
// verbatim.

type JObj struct {
	Keys []string
	Vals map[string]any
	Raw  []byte
}

func (o *JObj) Get(k string) any {
	if o == nil {
		return nil
	}
	return o.Vals[k]
}

type scanState struct {
	b   []byte
	i   int
	end int
}

func scanOrdered(b []byte) (any, error) {
	s := &scanState{b: b, end: len(b)}
	v, err := s.value()
	if err != nil {
		return nil, err
	}
	return v, nil
}

func (s *scanState) skipWS() {
	for s.i < s.end {
		switch s.b[s.i] {
		case ' ', '\t', '\n', '\r':
			s.i++
		default:
			return
		}
	}
}

func (s *scanState) value() (any, error) {
	s.skipWS()
	if s.i >= s.end {
		return nil, errEOF
	}
	switch c := s.b[s.i]; {
	case c == '{':
		start := s.i
		s.i++
		o := &JObj{Vals: map[string]any{}}
		s.skipWS()
		if s.i < s.end && s.b[s.i] == '}' {
			s.i++
			o.Raw = s.b[start:s.i]
			return o, nil
		}
		for {
			s.skipWS()
			if s.i >= s.end {
				return nil, errEOF
			}
			if s.b[s.i] != '"' {
				return nil, errUnexpected(s.b[s.i])
			}
			k, err := s.str()
			if err != nil {
				return nil, err
			}
			s.skipWS()
			if s.i >= s.end || s.b[s.i] != ':' {
				return nil, errUnexpected(s.b[s.i])
			}
			s.i++
			v, err := s.value()
			if err != nil {
				return nil, err
			}
			if _, dup := o.Vals[k]; !dup {
				o.Keys = append(o.Keys, k)
			}
			o.Vals[k] = v
			s.skipWS()
			if s.i >= s.end {
				return nil, errEOF
			}
			switch s.b[s.i] {
			case ',':
				s.i++
				continue
			case '}':
				s.i++
				o.Raw = s.b[start:s.i]
				return o, nil
			}
			return nil, errUnexpected(s.b[s.i])
		}
	case c == '[':
		start := s.i
		s.i++
		var arr []any
		s.skipWS()
		if s.i < s.end && s.b[s.i] == ']' {
			s.i++
			return &JArr{Items: arr, Raw: s.b[start:s.i]}, nil
		}
		for {
			v, err := s.value()
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
			s.skipWS()
			if s.i >= s.end {
				return nil, errEOF
			}
			switch s.b[s.i] {
			case ',':
				s.i++
				continue
			case ']':
				s.i++
				return &JArr{Items: arr, Raw: s.b[start:s.i]}, nil
			}
			return nil, errUnexpected(s.b[s.i])
		}
	case c == '"':
		v, err := s.str()
		if err != nil {
			return nil, err
		}
		return v, nil
	case c == 't':
		if s.i+4 <= s.end && string(s.b[s.i:s.i+4]) == "true" {
			s.i += 4
			return true, nil
		}
		return nil, errUnexpected(s.b[s.i])
	case c == 'f':
		if s.i+5 <= s.end && string(s.b[s.i:s.i+5]) == "false" {
			s.i += 5
			return false, nil
		}
		return nil, errUnexpected(s.b[s.i])
	case c == 'n':
		if s.i+4 <= s.end && string(s.b[s.i:s.i+4]) == "null" {
			s.i += 4
			return nil, nil
		}
